import json
p=json.load(open('.exp_agent/round_plan_01.json')); target={'@performance/hp-arkui-remove-unchanged-state-var','@performance/hp-arkui-remove-redundant-state-var'}
by={}
for r in p['rules']:
 if r['rule'] in target:
  for f in r['files']:
   by.setdefault(f['relative_path'],set()).update(x['line'] for x in f['locations'])
print('*** Begin Patch')
count=0
for path,nums in by.items():
 old=open(path).read().splitlines(); changed=[]
 for n in sorted(nums):
  if 1<=n<=len(old) and old[n-1].lstrip().startswith('@State '): changed.append(n-1)
 if not changed: continue
 print('*** Update File: '+path)
 count += len(changed)
 # contiguous runs, with one unchanged context line around each
 runs=[]; start=prev=changed[0]
 for i in changed[1:]:
  if i==prev+1: prev=i
  else: runs.append((start,prev)); start=prev=i
 runs.append((start,prev))
 for a,b in runs:
  lo=max(0,a-1); hi=min(len(old),b+2)
  print('@@')
  for i in range(lo,hi):
   if a<=i<=b:
    print('-'+old[i]); print('+'+old[i].replace('@State ','',1))
   else: print(' '+old[i])
print('*** End Patch',file=__import__('sys').stdout)
print(f'files={sum(1 for nums in by.values() if nums)} changes={count}',file=__import__('sys').stderr)
